using Poly.Interpretation.CSharp;

namespace Poly.Tests.Interpretation;

/// <summary>
/// E-01 (#685): <see cref="CSharpWriter.Write(CompilationUnitNode)"/> prints one
/// deterministic header — an auto-generated banner, exactly one nullable directive,
/// and explicit-plus-inferred usings sorted System-first — and
/// <see cref="CSharpReader"/> consumes the banner so <c>Write(Read(x))</c> holds.
/// The <c>Write(typeDefs)</c> overload stays header-identical until E-03.
/// </summary>
public class CSharpWriterUnitTests {
    private const string Banner = "// <auto-generated/>";

    private static int Occurrences(string text, string token) {
        var count = 0;
        for (var index = text.IndexOf(token, StringComparison.Ordinal);
             index >= 0;
             index = text.IndexOf(token, index + token.Length, StringComparison.Ordinal))
            count++;
        return count;
    }

    private static int CountComments(Node node, string text) {
        var count = node is Comment comment && comment.Text == text ? 1 : 0;
        foreach (var child in node.Children) {
            if (child is not null)
                count += CountComments(child, text);
        }
        return count;
    }

    private static CompilationUnitNode Unit(string? ns, IReadOnlyList<string> usings, params TypeDefinitionNode[] types) =>
        new(usings, ns, types, TopLevelStatements: null);

    private static TypeDefinitionNode ClassWithDateAndList() => new(
        "Cart",
        Fields: [
            new FieldDefinitionNode(
                "Items",
                new NamedTypeReference("List", TypeArguments: [
                    new PrimitiveTypeReference(Poly.Introspection.PrimitiveType.Int32),
                ])),
            new FieldDefinitionNode("PlacedOn", new NamedTypeReference("DateOnly")),
        ]);

    [Test]
    public async Task Write_Unit_InfersMergesAndSortsUsings_OneNullableHeader() {
        var unit = Unit(
            "Demo.Shop",
            ["System.Text.Json", "SystemTools.X", "Poly.Generated"],
            ClassWithDateAndList());

        var text = CSharpLanguage.Write(unit);

        var expectedHeader =
            "// <auto-generated/>\n" +
            "\n" +
            "#nullable enable\n" +
            "\n" +
            "using System;\n" +
            "using System.Collections.Generic;\n" +
            "using System.Text.Json;\n" +
            "using Poly.Generated;\n" +
            "using SystemTools.X;\n" +
            "\n" +
            "namespace Demo.Shop;\n" +
            "\n";
        await Assert.That(text.StartsWith(expectedHeader, StringComparison.Ordinal)).IsTrue()
            .Because(text);
        await Assert.That(Occurrences(text, "#nullable enable")).IsEqualTo(1);
        await Assert.That(Occurrences(text, Banner)).IsEqualTo(1);
        await Assert.That(Occurrences(text, "using System;")).IsEqualTo(1);
        await Assert.That(Occurrences(text, "using System.Collections.Generic;")).IsEqualTo(1);
    }

    [Test]
    public async Task Write_Unit_EmptyUsings_HeaderShape() {
        var text = CSharpLanguage.Write(Unit("Demo", [], new TypeDefinitionNode("Empty")));

        // Exactly one blank line between the directive and the namespace: no double gap.
        await Assert.That(
            text.StartsWith("// <auto-generated/>\n\n#nullable enable\n\nnamespace Demo;\n\npublic class Empty", StringComparison.Ordinal))
            .IsTrue().Because(text);
        await Assert.That(Occurrences(text, "\n\n\n")).IsEqualTo(0);
    }

    [Test]
    public async Task Write_Unit_BannerMarksFileGenerated() {
        var text = CSharpLanguage.Write(Unit("Demo", ["System"], new TypeDefinitionNode("Empty")));

        await Assert.That(text.StartsWith(Banner + "\n", StringComparison.Ordinal)).IsTrue().Because(text);
        await Assert.That(text.Contains("Requires:", StringComparison.Ordinal)).IsFalse();
    }

    [Test]
    public async Task Write_TypeDefs_HeaderIsUnchangedUntilE03() {
        // PIN: green before and after E-01. E-03 flips this overload to the unit header.
        var text = CSharpLanguage.Write([new TypeDefinitionNode("Empty")]);

        await Assert.That(text.StartsWith("#nullable enable\n", StringComparison.Ordinal)).IsTrue().Because(text);
        await Assert.That(text.Contains(Banner, StringComparison.Ordinal)).IsFalse();
        await Assert.That(Occurrences(text, "#nullable enable")).IsEqualTo(1);
    }

    [Test]
    public async Task Write_Read_Write_IsIdempotent_WithBanner() {
        const string source =
            "// <auto-generated/>\n" +
            "\n" +
            "#nullable enable\n" +
            "\n" +
            "namespace Demo;\n" +
            "\n" +
            "public class C\n" +
            "{\n" +
            "    public void M()\n" +
            "    {\n" +
            "        var x = 1;\n" +
            "    }\n" +
            "}";

        var once = CSharpLanguage.Write(CSharpLanguage.Read(source));
        var twice = CSharpLanguage.Write(CSharpLanguage.Read(once));

        await Assert.That(once.StartsWith(Banner + "\n", StringComparison.Ordinal)).IsTrue().Because(once);
        await Assert.That(Occurrences(once, Banner)).IsEqualTo(1).Because(once);
        await Assert.That(once.IndexOf(Banner, StringComparison.Ordinal))
            .IsLessThan(once.IndexOf("class C", StringComparison.Ordinal));
        await Assert.That(twice).IsEqualTo(once);
    }

    [Test]
    public async Task Read_LeadingNonBannerComment_IsKept() {
        // PIN: green before and after E-01. Only the generated banner is header trivia.
        const string source =
            "// keep me\n" +
            "\n" +
            "public class C\n" +
            "{\n" +
            "    public void M()\n" +
            "    {\n" +
            "        var x = 1;\n" +
            "    }\n" +
            "}";

        var unit = CSharpLanguage.Read(source);

        await Assert.That(CountComments(unit, "keep me")).IsEqualTo(1);
    }

    [Test]
    public async Task Read_BannerNotAtLine1Col1_StaysAComment() {
        // PIN: green before and after E-01. An offset banner is an ordinary comment.
        const string source =
            "\n" +
            "// <auto-generated/>\n" +
            "\n" +
            "public class C\n" +
            "{\n" +
            "    public void M()\n" +
            "    {\n" +
            "        var x = 1;\n" +
            "    }\n" +
            "}";

        var unit = CSharpLanguage.Read(source);

        await Assert.That(CountComments(unit, "<auto-generated/>")).IsEqualTo(1);
    }

    [Test]
    public async Task Write_Unit_UsingThatIsNotADottedName_Throws() {
        var unit = Unit(null, ["@shop"], new TypeDefinitionNode("Empty"));

        await Assert.That(() => CSharpLanguage.Write(unit))
            .Throws<InvalidOperationException>()
            .WithMessageContaining("@shop");
    }

    [Test]
    [Arguments("Shop.class")]
    [Arguments("global::Shop")]
    [Arguments("@shop")]
    public async Task Write_Unit_NamespaceThatIsNotADottedName_Throws(string ns) {
        var unit = Unit(ns, [], new TypeDefinitionNode("Empty"));

        await Assert.That(() => CSharpLanguage.Write(unit))
            .Throws<InvalidOperationException>()
            .WithMessageContaining(ns);
    }

    // ── R-03b / A6: the type-list header contract ────────────────────────────
    //
    // #nullable enable, then the System group, a blank line, the Poly group, a
    // blank line, then the body. A group appears only when one of its identifiers
    // is present, and with neither group the header is unchanged.

    private static TypeDefinitionNode Cart(params FieldDefinitionNode[] fields) =>
        new("Cart", Fields: [.. fields]);

    private static string WriteCart(params FieldDefinitionNode[] fields) =>
        CSharpLanguage.Write([Cart(fields)]);

    private static async Task AssertHeader(string expectedHeader, string text) {
        await Assert.That(text.StartsWith(expectedHeader, StringComparison.Ordinal))
            .IsTrue().Because(text);
        await Assert.That(text[expectedHeader.Length..].StartsWith("public class Cart", StringComparison.Ordinal))
            .IsTrue().Because(text);
    }

    [Test]
    public async Task Write_TypeDefs_Header_NeitherGroup() {
        var text = WriteCart(new FieldDefinitionNode("Label", new NamedTypeReference("Text")));

        await AssertHeader("#nullable enable\n", text);
    }

    [Test]
    public async Task Write_TypeDefs_Header_SystemGroupOnly() {
        var text = WriteCart(
            new FieldDefinitionNode("PlacedOn", new NamedTypeReference("DateOnly")),
            new FieldDefinitionNode("Items", new NamedTypeReference("List", TypeArguments: [
                new PrimitiveTypeReference(Poly.Introspection.PrimitiveType.Int32),
            ])));

        await AssertHeader(
            "#nullable enable\n" +
            "using System;\n" +
            "using System.Collections.Generic;\n" +
            "\n",
            text);
    }

    [Test]
    public async Task Write_TypeDefs_Header_PolyGroupOnly() {
        var text = WriteCart(
            new FieldDefinitionNode("Result", new NamedTypeReference("DomainResult", TypeArguments: [
                new NamedTypeReference("Item"),
            ])));

        await AssertHeader(
            "#nullable enable\n" +
            "using Poly.Runtime;\n" +
            "\n",
            text);
    }

    [Test]
    public async Task Write_TypeDefs_Header_BothGroupsWithSeparatingBlankLine() {
        var text = WriteCart(
            new FieldDefinitionNode("PlacedOn", new NamedTypeReference("DateOnly")),
            new FieldDefinitionNode("Result", new NamedTypeReference("DomainResult", TypeArguments: [
                new NamedTypeReference("Item"),
            ])),
            new FieldDefinitionNode("Failure", new NamedTypeReference("ConstraintFailureException")));

        await AssertHeader(
            "#nullable enable\n" +
            "using System;\n" +
            "\n" +
            "using Poly.DomainModeling.Runtime;\n" +
            "using Poly.Runtime;\n" +
            "\n",
            text);
    }

    [Test]
    public async Task Write_TypeDefs_Header_DomainResultLookalikes_AddNoPolyRuntimeUsing() {
        var text = WriteCart(
            new FieldDefinitionNode("A", new NamedTypeReference("MyDomainResult")),
            new FieldDefinitionNode("B", new NamedTypeReference("DomainResultFoo")));

        await AssertHeader("#nullable enable\n", text);
    }

    [Test]
    public async Task Write_TypeDefs_Header_ConstraintFailureLookalikes_AddNoDomainModelingRuntimeUsing() {
        var text = WriteCart(
            new FieldDefinitionNode("A", new NamedTypeReference("ConstraintFailureExceptionX")),
            new FieldDefinitionNode("B", new NamedTypeReference("MyConstraintFailureException")));

        await AssertHeader("#nullable enable\n", text);
    }

    [Test]
    public async Task Write_TypeDefs_Header_LookalikeBesideRealDomainResult_AddsOnePolyRuntimeUsing() {
        var text = WriteCart(
            new FieldDefinitionNode("A", new NamedTypeReference("MyDomainResult")),
            new FieldDefinitionNode("Result", new NamedTypeReference("DomainResult", TypeArguments: [
                new NamedTypeReference("Item"),
            ])));

        await AssertHeader(
            "#nullable enable\n" +
            "using Poly.Runtime;\n" +
            "\n",
            text);
        await Assert.That(text.Split("using Poly.Runtime;").Length - 1).IsEqualTo(1);
    }

    // ── E-03 / A2: the unit path infers the Poly.Runtime usings the type-list path does ─────

    private static string WriteCartUnit(params FieldDefinitionNode[] fields) =>
        CSharpLanguage.Write(Unit("Shop", [], Cart(fields)));

    [Test]
    public async Task Write_Unit_DomainResult_InfersOnePolyRuntimeUsing() {
        var text = WriteCartUnit(
            new FieldDefinitionNode("Result", new NamedTypeReference("DomainResult", TypeArguments: [
                new NamedTypeReference("Item"),
            ])));

        await Assert.That(text).Contains("using Poly.Runtime;\n");
        await Assert.That(Occurrences(text, "using Poly.Runtime;")).IsEqualTo(1);
        await Assert.That(text).DoesNotContain("using Poly.DomainModeling.Runtime;");
    }

    [Test]
    public async Task Write_Unit_ConstraintFailure_InfersDomainModelingRuntimeUsing() {
        var text = WriteCartUnit(
            new FieldDefinitionNode("Failure", new NamedTypeReference("ConstraintFailureException")));

        await Assert.That(text).Contains("using Poly.DomainModeling.Runtime;\n");
        await Assert.That(text).DoesNotContain("using Poly.Runtime;");
    }

    [Test]
    public async Task Write_Unit_DomainResultLookalikes_AddNoPolyRuntimeUsing() {
        var text = WriteCartUnit(
            new FieldDefinitionNode("A", new NamedTypeReference("MyDomainResult")),
            new FieldDefinitionNode("B", new NamedTypeReference("DomainResultFoo")),
            new FieldDefinitionNode("C", new NamedTypeReference("ConstraintFailureExceptionX")));

        await Assert.That(text).DoesNotContain("using Poly.");
    }

    [Test]
    public async Task Write_Unit_LookalikeBesideRealDomainResult_AddsOnePolyRuntimeUsing() {
        var text = WriteCartUnit(
            new FieldDefinitionNode("A", new NamedTypeReference("MyDomainResult")),
            new FieldDefinitionNode("Result", new NamedTypeReference("DomainResult", TypeArguments: [
                new NamedTypeReference("Item"),
            ])));

        await Assert.That(Occurrences(text, "using Poly.Runtime;")).IsEqualTo(1);
    }

    [Test]
    public async Task Write_Unit_ExplicitUsingsThatDuplicateInferredOnes_AppearOnce() {
        var text = CSharpLanguage.Write(Unit(
            "Shop",
            ["System", "System.Collections.Generic", "System", "Poly.Runtime"],
            ClassWithDateAndList(),
            Cart(new FieldDefinitionNode("Result", new NamedTypeReference("DomainResult", TypeArguments: [
                new NamedTypeReference("Item"),
            ])))));

        await Assert.That(Occurrences(text, "using System;")).IsEqualTo(1);
        await Assert.That(Occurrences(text, "using System.Collections.Generic;")).IsEqualTo(1);
        await Assert.That(Occurrences(text, "using Poly.Runtime;")).IsEqualTo(1);
    }

    // ── E-03 / A14 items 2, 3: using-side validation and banner/comment placement ───────────

    [Test]
    [Arguments("Shop.class")]
    [Arguments("A = B")]
    [Arguments("static System.Math")]
    [Arguments("A..B")]
    [Arguments("")]
    [Arguments("System.")]
    [Arguments("1Shop")]
    public async Task Write_Unit_UsingThatIsNotAnIdentifierSequence_Throws(string name) {
        var unit = Unit(null, [name], new TypeDefinitionNode("Empty"));

        await Assert.That(() => CSharpLanguage.Write(unit)).Throws<InvalidOperationException>();
    }

    [Test]
    [Arguments("System.Net.Http2")]
    [Arguments("_Internal.X1")]
    public async Task Write_Unit_UsingThatIsAnIdentifierSequence_IsAccepted(string name) {
        var text = CSharpLanguage.Write(Unit(null, [name], new TypeDefinitionNode("Empty")));

        await Assert.That(text).Contains($"using {name};");
    }

    [Test]
    public async Task Write_Unit_KeywordRejection_NamesTheInterimUntilE10() {
        var unit = Unit("Shop.class", [], new TypeDefinitionNode("Empty"));

        await Assert.That(() => CSharpLanguage.Write(unit))
            .Throws<InvalidOperationException>()
            .WithMessageContaining("E-10");
    }

    [Test]
    public async Task Read_BannerInsideBlockComment_StaysAComment() {
        const string source =
            "/* // <auto-generated/> */\n" +
            "\n" +
            "public class C\n" +
            "{\n" +
            "    public void M()\n" +
            "    {\n" +
            "        var x = 1;\n" +
            "    }\n" +
            "}";

        var unit = CSharpLanguage.Read(source);

        await Assert.That(CountComments(unit, "// <auto-generated/>")).IsGreaterThanOrEqualTo(1);
    }

    [Test]
    public async Task Write_Read_BodyComment_IsKeptAndRoundTrips() {
        const string source =
            "// <auto-generated/>\n" +
            "\n" +
            "#nullable enable\n" +
            "\n" +
            "namespace Demo;\n" +
            "\n" +
            "public class C\n" +
            "{\n" +
            "    public void M()\n" +
            "    {\n" +
            "        // inner\n" +
            "        var x = 1;\n" +
            "    }\n" +
            "}";

        var once = CSharpLanguage.Write(CSharpLanguage.Read(source));

        await Assert.That(once).Contains("// inner");
        await Assert.That(CSharpLanguage.Write(CSharpLanguage.Read(once))).IsEqualTo(once);
    }

    // ── E-03 / A14 item 4: every regenerated unit golden survives Write(Read(x)) unchanged ──

    public static IEnumerable<string> UnitGoldenFiles() {
        var root = AppContext.BaseDirectory;
        while (root is not null && !File.Exists(Path.Combine(root, "docs/CORE.md")))
            root = Directory.GetParent(root)?.FullName;
        var emit = Path.Combine(root!, "Poly.Tests", "DomainModeling", "Compile", "EmitGolden");
        return Directory.GetFiles(emit, "*.cs.golden", SearchOption.AllDirectories)
            .Select(path => Path.GetRelativePath(root!, path))
            .Where(path => File.ReadAllText(Path.Combine(root!, path)).StartsWith(Banner, StringComparison.Ordinal))
            .Order(StringComparer.Ordinal);
    }

    // Findings, not exemptions: each file below diverges today for the stated reason, and the test below pins
    // that it still does, so fixing the reader or writer removes the row instead of leaving it stale.
    private static readonly Dictionary<string, string> KnownRoundTripFindings = new(StringComparer.Ordinal) {
        ["Poly.Tests/DomainModeling/Compile/EmitGolden/university/Enrollment.cs.golden"] =
            "DateTime.UtcNow re-prints as System.DateTime.UtcNow",
        ["Poly.Tests/DomainModeling/Compile/EmitGolden/crm/Activity.cs.golden"] =
            "DateTime.UtcNow re-prints as System.DateTime.UtcNow",
        ["Poly.Tests/DomainModeling/Compile/EmitGolden/crm/Opportunity.cs.golden"] =
            "DateTime.UtcNow re-prints as System.DateTime.UtcNow",
        ["Poly.Tests/DomainModeling/Compile/EmitGolden/crm-dslcompiler/Program.cs.golden"] =
            "the [Range(typeof(decimal), ...)] attribute (first difference, line 1366) does not round-trip",
    };

    [Test]
    [MethodDataSource(nameof(UnitGoldenFiles))]
    public async Task Write_Read_UnitGolden_IsUnchanged(string relativePath) {
        var root = AppContext.BaseDirectory;
        while (root is not null && !File.Exists(Path.Combine(root, "docs/CORE.md")))
            root = Directory.GetParent(root)?.FullName;
        var golden = (await File.ReadAllTextAsync(Path.Combine(root!, relativePath))).Replace("\r\n", "\n");

        var round = CSharpLanguage.Write(CSharpLanguage.Read(golden));

        if (KnownRoundTripFindings.TryGetValue(relativePath.Replace('\\', '/'), out var finding))
            await Assert.That(round).IsNotEqualTo(golden).Because($"known finding no longer reproduces: {finding}");
        else
            await Assert.That(round).IsEqualTo(golden);
    }
}